static kstat_t * agg_vm ( struct pset_snapshot * p , kstat_t * ks ) { size_t i ; if ( kstat_copy ( & p -> ps_cpus [ 0 ] -> cs_vm , ks ) ) { return ( NULL ) ; } for ( i = 1 ; i < p -> ps_nr_cpus ; i ++ ) { agg_stat ( ks , & p -> ps_cpus [ i ] -> cs_vm , "hat_fault" ) ; agg_stat ( ks , & p -> ps_cpus [ i ] -> cs_vm , "as_fault" ) ; agg_stat ( ks , & p -> ps_cpus [ i ] -> cs_vm , "maj_fault" ) ; } return ( ks ) ; } 